import math

def find_smallest_cube(limit_k=100, limit_a=200):
    """Find smallest cube number that is sum of two positive cubes in two different ways."""

    cubes = [i**3 for i in range(1, limit_a + 1)]

    # Dictionary to store cube sums and their representations
    cube_sums = {}

    # Generate all sums of cubes
    for i in range(1, limit_a + 1):
        for j in range(i + 1, limit_a + 1):
            s = cubes[i-1] + cubes[j-1]
            if s not in cube_sums:
                cube_sums[s] = []
            cube_sums[s].append((i, j))

    # Check each cube number
    for k in range(1, limit_k + 1):
        n = k**3
        if n in cube_sums and len(cube_sums[n]) >= 2:
            # Check that the pairs are different
            pairs = cube_sums[n]
            # Make sure pairs are actually different
            if len(pairs) >= 2 and pairs[0] != pairs[1]:
                return k, n, pairs

    return None

# Try with larger limits
result = None
for limit in [50, 100, 150, 200]:
    print(f"Searching up to k={limit}...")
    result = find_smallest_cube(limit_k=limit, limit_a=limit*2)
    if result:
        break

if result:
    k, n, pairs = result
    print(f"\nFound: {k}³ = {n}")
    print(f"It can be expressed as:")
    for a, b in pairs[:2]:  # Show first 2 representations
        print(f"  {a}³ + {b}³ = {a**3} + {b**3} = {a**3 + b**3}")
else:
    print("Not found within search limits")

