# Dictionary mapping sum to list of pairs
sum_map = {}

for a in range(1, max_val + 1):
    a3 = cubes[a]
    for b in range(a + 1, max_val + 1):
        b3 = cubes[b]
        s = a3 + b3

        # Check if s is a perfect cube
        k = round(s ** (1/3))
        if k <= max_val and cubes[k] == s:
            # s is a perfect cube!
            if s not in sum_map:
                sum_map[s] = []
            sum_map[s].append((a, b))

# Check for sums with multiple representations that are perfect cubes
for s, pairs in sum_map.items():
    if len(pairs) >= 2:
        k = round(s ** (1/3))
        print(f"Found: {k}³ = {s}")
        for a, b in pairs:
            print(f"  {a}³ + {b}³ = {a**3} + {b**3} = {s}")
